import unittest
from candidate import sort_numbers

class TestSortNumbers(unittest.TestCase):
    def test_sort_numbers_normal_case(self):
        self.assertEqual(sort_numbers('three one five'), 'one three five')

    def test_sort_numbers_single_input(self):
        self.assertEqual(sort_numbers('five'), 'five')

    def test_sort_numbers_empty_input(self):
        self.assertEqual(sort_numbers(''), '')

    def test_sort_numbers_none_input(self):
        with self.assertRaises(TypeError):
            sort_numbers(None)

    def test_sort_numbers_invalid_input(self):
        with self.assertRaises(KeyError):
            sort_numbers('ten two')

    def test_sort_numbers_duplicate_input(self):
        self.assertEqual(sort_numbers('one two two'), 'one two two')

    def test_sort_numbers_large_input(self):
        input_string = 'nine eight seven six five four three two one'
        self.assertEqual(sort_numbers(input_string), 'one two three four five six seven eight nine')

    def test_sort_numbers_input_with_spaces(self):
        self.assertEqual(sort_numbers('   three   one   five   '), 'one three five')

    def test_sort_numbers_input_with_punctuation(self):
        with self.assertRaises(ValueError):
            sort_numbers('one, two, three')

    def test_sort_numbers_input_with_numbers(self):
        with self.assertRaises(ValueError):
            sort_numbers('1 2 3')

if __name__ == '__main__':
    unittest.main()
